import{_ as e,o as d,c as o,a5 as a}from"./chunks/framework.BqnnR8ku.js";const u=JSON.parse('{"title":"翻译审校","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/review.md","filePath":"zh/guide/review.md"}'),i={name:"zh/guide/review.md"};function s(c,t,r,l,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="翻译审校" tabindex="-1">翻译审校 <a class="header-anchor" href="#翻译审校" aria-label="Permalink to &quot;翻译审校&quot;">​</a></h1><p>翻译审校功能帮助您确保翻译质量，支持逐段审校、质量高亮定位和批量操作。</p><h2 id="审校流程" tabindex="-1">审校流程 <a class="header-anchor" href="#审校流程" aria-label="Permalink to &quot;审校流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>翻译完成 → 质检标记 → 逐段查看质量结果 → 审批 / 拒绝 → 质量裁决（可选）→ 语义质检（可选）→ 完成</span></span></code></pre></div><p>翻译作业完成后的段落状态为「已翻译」，进入审校阶段。您也可以在创建翻译作业时开启 <strong>自动审批</strong>，跳过审校流程。</p><h2 id="段落状态" tabindex="-1">段落状态 <a class="header-anchor" href="#段落状态" aria-label="Permalink to &quot;段落状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>说明</th><th>可转换为</th></tr></thead><tbody><tr><td>待审校 (<code>pending</code>)</td><td>等待翻译</td><td>—</td></tr><tr><td>已翻译 (<code>translated</code>)</td><td>AI 翻译完成，等待审校</td><td>已批准、已驳回、已修改</td></tr><tr><td>已修改 (<code>edited</code>)</td><td>译文被人工修改后的状态</td><td>已批准、已驳回</td></tr><tr><td>已批准 (<code>approved</code>)</td><td>审校通过</td><td>已修改（再次编辑）</td></tr><tr><td>已驳回 (<code>rejected</code>)</td><td>审校不通过</td><td>已批准、已修改、待审校（重新翻译）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">审校操作已精简</p><p>审校动作只保留 <strong>审批（approve）</strong> 与 <strong>拒绝（reject）</strong> 两种。要让某段译文修订而不立即通过/拒绝，请改用段落编辑/更新入口修改译文文本——译文一旦被改过，状态会变为「已修改」(<code>edited</code>)。</p></div><div class="tip custom-block"><p class="custom-block-title">状态流转</p><ul><li>审批操作可从「已翻译」「已修改」「已驳回」转换为「已批准」</li><li>拒绝操作可从「已翻译」「已修改」转换为「已驳回」</li><li>已批准的段落若需修订，先修改译文变回「已修改」，再决定是否审批/拒绝</li></ul></div><h2 id="逐段审校" tabindex="-1">逐段审校 <a class="header-anchor" href="#逐段审校" aria-label="Permalink to &quot;逐段审校&quot;">​</a></h2><p>翻译完成后，在工作区的段落列表中逐段查看和审校翻译结果。</p><h3 id="审校界面" tabindex="-1">审校界面 <a class="header-anchor" href="#审校界面" aria-label="Permalink to &quot;审校界面&quot;">​</a></h3><p>每段显示以下信息：</p><ul><li><strong>源文本</strong> — 原始内容，可切换查看 HTML 源码</li><li><strong>翻译文本</strong> — AI 翻译结果，质量问题会在译文中直接高亮</li><li><strong>状态标签</strong> — 带图标和颜色的状态标识（蓝色=待审校，绿色=已批准，红色=已驳回）</li><li><strong>质量指示</strong> — 在译文单元格内以颜色块与下划线标出问题区间，悬停/点击可查看问题 code 与说明</li><li><strong>审校批注</strong> — 审校者添加的备注信息，点击可展开查看</li></ul><h3 id="质量问题高亮" tabindex="-1">质量问题高亮 <a class="header-anchor" href="#质量问题高亮" aria-label="Permalink to &quot;质量问题高亮&quot;">​</a></h3><p>规则质检和语义质检产生的问题会带 <code>span</code>（精确的源/译片段位置），段落列表会把这些问题区间在译文里高亮出来：</p><ul><li><strong>红色 / 橙色背景</strong> — 按 <code>severity</code> 区分 <code>error</code> 与 <code>warning</code></li><li><strong>悬停联动</strong> — 鼠标悬停问题图标，对应文本区间高亮；反之亦然（移动端为点击联动）</li><li><strong>重叠区间</strong> — 多个问题落在同一段文字时自动合并显示，避免视觉混乱</li></ul><h3 id="段落导航" tabindex="-1">段落导航 <a class="header-anchor" href="#段落导航" aria-label="Permalink to &quot;段落导航&quot;">​</a></h3><p>段落表格支持键盘上下导航：</p><ul><li><strong>↑ / ↓</strong> 键移动聚焦行</li><li>自动滚动确保聚焦行不会被表格头部遮挡</li></ul><h3 id="审校操作" tabindex="-1">审校操作 <a class="header-anchor" href="#审校操作" aria-label="Permalink to &quot;审校操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th><th>状态变化</th></tr></thead><tbody><tr><td>✅ 审批</td><td>确认翻译正确</td><td>→ <code>approved</code></td></tr><tr><td>❌ 拒绝</td><td>标记翻译有问题</td><td>→ <code>rejected</code></td></tr></tbody></table><h3 id="修改译文" tabindex="-1">修改译文 <a class="header-anchor" href="#修改译文" aria-label="Permalink to &quot;修改译文&quot;">​</a></h3><p>需要修订译文时，使用段落的更新入口：</p><ol><li>在段落行的编辑入口中修改译文文本（与可选批注）</li><li>保存后状态自动转为「已修改」(<code>edited</code>)</li><li>保存时会自动对译文跑一遍<strong>零配置确定性 QA</strong>（无需执行计划配置）：覆盖 <code>untranslated</code>、<code>source_residual</code>、<code>punctuation_pairing</code>、<code>punctuation_missing</code>、<code>punctuation_surplus</code>、<code>punctuation_wrap_loss</code>、<code>whitespace_irregular</code>、<code>repeated_space</code>、<code>width_mix</code>、<code>script_mismatch</code>、<code>number_mismatch</code>、<code>url_email_mismatch</code>、<code>subtitle_line_count</code>、<code>leftover_placeholder</code>、<code>xml_tag_mismatch</code> 共 15 项即时判定，质量问题会实时更新到该段；若编辑前译文含 <code>&lt;ruby&gt;</code> 注音、编辑后全丢，还会产出 <code>ruby_tag_loss</code> 软警告（可驳回，不阻塞保存）</li><li>之后仍需在「已修改」状态下决定 <strong>审批</strong> 或 <strong>拒绝</strong></li></ol><div class="info custom-block"><p class="custom-block-title">只改译文，不改原文</p><p>段落编辑入口仅支持修改译文与批注，不能改动源文。依赖长度比阈值、术语表或多段/文档级比对的检查（<code>length_ratio</code>、<code>forbidden_term</code>、<code>term_inconsistency</code>、<code>duplicate</code>、<code>duplicate_source_divergence</code>）不在即时 QA 范围内，仍由翻译轮次或后续审校处理。</p></div><h2 id="质量检测" tabindex="-1">质量检测 <a class="header-anchor" href="#质量检测" aria-label="Permalink to &quot;质量检测&quot;">​</a></h2><p>LinguaFlow 在翻译完成后自动检测译文中可能存在的问题，涉及五类机制：</p><ul><li><strong>规则质检（确定性 QA）</strong>：纯规则、本地执行、可靠可复现；在翻译轮次内随执行配置自动运行并写回段落</li><li><strong>本地改写（<code>correct</code>）</strong>：可选的执行计划轮次，机械修复规则质检报出的高频安全问题子集（如补回丢失的引号），纯本地、不调 LLM、不新增问题</li><li><strong>LLM 修订（<code>revise</code>）</strong>：可选的执行计划轮次，以段落上 <code>pending</code> 的语义问题为修复目标，对现有译文做最小改动的定点修订（不重译）；系统提示词内置</li><li><strong>语义质检（LLM 语义 QA）</strong>：可选的执行计划轮次 <code>semantic_qa</code>，捕获规则无法覆盖的语义错误，产 <code>warning</code> 级问题直接进人审</li><li><strong>质量裁决（<code>adjudicate</code>）</strong>：对软规则问题逐条问 AI 做误报判定，<code>false_positive</code> 的问题标记为 <code>dismissed</code>（保留记录、后续轮次跳过），<strong>不新增问题</strong></li></ul><h3 id="历史与用途" tabindex="-1">历史与用途 <a class="header-anchor" href="#历史与用途" aria-label="Permalink to &quot;历史与用途&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>何时跑</th><th>是否新增问题</th><th>严重级别</th><th>是否可入选工作流裁决</th></tr></thead><tbody><tr><td>规则质检</td><td>翻译轮次内、同步</td><td>是</td><td><code>error</code> / <code>warning</code></td><td>软规则可裁决</td></tr><tr><td>本地改写（<code>correct</code> 轮次）</td><td>执行计划中安排的轮次（翻译后）</td><td>否（只改写）</td><td>—</td><td>—</td></tr><tr><td>LLM 修订（<code>revise</code> 轮次）</td><td>执行计划中安排的轮次（翻译后）</td><td>否（只改写）</td><td>—</td><td>—</td></tr><tr><td>语义质检（<code>semantic_qa</code> 轮次）</td><td>执行计划中安排的轮次</td><td>是</td><td><code>warning</code></td><td>否（直接进人审）</td></tr><tr><td>质量裁决（<code>adjudicate</code> 轮次）</td><td>执行计划中安排的轮次</td><td>否</td><td>—</td><td>—</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">改写类、新增类、裁决类各管一段</p><ul><li><code>correct</code> / <code>revise</code> 都<strong>改写译文</strong>以消除已报出的问题：<code>correct</code> 纯本地机械修复高频安全问题、不调 LLM；<code>revise</code> 调 LLM 按语义 issue 做定点最小修订。两者都沿用 correct 的幂等契约——改写后重跑确定性 QA 验证，改不掉就回滚，避免把「没修好」伪装成「已修好」</li><li><code>adjudicate</code> 只判断已有软规则问题<strong>保留 / 标记为 <code>dismissed</code></strong>、不改译文</li><li><code>semantic_qa</code> <strong>新增</strong>语义类问题</li></ul><p>四者互补，都放在翻译轮次之后，不冲突。详见 <a href="/LinguaFlow/zh/guide/pipeline.html#规则质检与-ai-质量裁决">流水线与原理 · 规则质检与 AI 质量裁决</a>。</p></div><h3 id="规则质检-code-一览" tabindex="-1">规则质检 code 一览 <a class="header-anchor" href="#规则质检-code-一览" aria-label="Permalink to &quot;规则质检 code 一览&quot;">​</a></h3><p>执行配置 <code>qa.checks</code> 为 <code>nil</code> 时启用全部；非 <code>nil</code> 时按名称过滤。下表为完整清单（含 1 项文档级检查）。</p><table tabindex="0"><thead><tr><th>code</th><th>说明</th><th>级别</th><th>可裁决</th><th>文档级</th></tr></thead><tbody><tr><td><code>length_ratio</code></td><td>译文长度相对原文过短/过长（按字符或词计算）</td><td>error/warning</td><td>✅ 软规则</td><td></td></tr><tr><td><code>duplicate</code></td><td><strong>相邻</strong>段落译文完全相同</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>duplicate_source_divergence</code></td><td><strong>文档级</strong>：规范化相同源文段却出现不同译文（跨段同源异译）</td><td>warning</td><td>❌</td><td>✅</td></tr><tr><td><code>untranslated</code></td><td>译文与原文完全一致，疑似未译</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>source_residual</code></td><td>译文夹带源语脚本片段（假名、谚文、西里尔文、汉字残留等），按语言对分档</td><td>warning</td><td>✅ 软规则</td><td></td></tr><tr><td><code>punctuation_pairing</code></td><td>目标语引号/括号/书名号等配对不平衡</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>punctuation_missing</code></td><td>源文整类包裹标点（引号、括号等）在译文中完全缺失</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>punctuation_surplus</code></td><td>译文多出源文所无的成对包裹标点（引号、括号等）</td><td>warning</td><td>✅ 软规则</td><td></td></tr><tr><td><code>punctuation_wrap_loss</code></td><td>源文整段被成对引号包裹，译文首尾完全丢失外层引号（补 <code>punctuation_missing</code> 对「内层新增引号致计数非零」的盲区）</td><td>warning</td><td>✅ 软规则</td><td></td></tr><tr><td><code>ruby_restore_incomplete</code></td><td>翻译轮该段应还原的 <code>&lt;ruby&gt;</code> 注音只还原了部分（应还原 N 条，实际 M 条）</td><td>warning</td><td>❌ 软规则</td><td></td></tr><tr><td><code>ruby_tag_loss</code></td><td>人工编辑把原本含 <code>&lt;ruby&gt;</code> 注音的译文改到一条注音不剩（按基线对比判定）</td><td>warning</td><td>❌ 软规则</td><td></td></tr><tr><td><code>whitespace_irregular</code></td><td>零宽字符、NBSP、制表符、行/段分隔符等异常空白</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>repeated_space</code></td><td>连续空格；CJK 目标语中字符间夹英文空格</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>width_mix</code></td><td>CJK 目标语中混入零歧义半角标点（<code>! ? , ; : ( ) [ ]</code>），或拉丁目标语中混入全角字符；数字写法如 <code>1,000</code>/<code>12:30</code>/<code>5!</code> 豁免</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>script_mismatch</code></td><td>多文字系统目标语言（如 <code>zh-Hans</code>/<code>zh-Hant</code>、<code>sr-Latn</code>/<code>sr-Cyrl</code>）的译文中出现兄弟文字系统专属字符（如简体译文混入繁体字），出现即报；单文字系统语言与 <code>auto</code> 不生效</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>number_mismatch</code></td><td>阿拉伯数字在源/译间不一致（归一化全角数字与千分位/小数分隔符后比对多重集合）</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>url_email_mismatch</code></td><td>源/译中超链接、邮箱地址集合不一致</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>subtitle_line_count</code></td><td>srt/ass/vtt 等字幕格式下，源/译行数不一致</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>forbidden_term</code></td><td>命中词表禁译（forbidden）条目，译文中却出现 target</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>term_inconsistency</code></td><td>命中强制（mandatory）条目，但译文未用 target 译法</td><td>warning</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>leftover_placeholder</code></td><td>译文中残留 <code>__LF_*</code> 占位符（缺失、重复或字形偏移等三类汇总）</td><td>error</td><td>❌ 硬规则</td><td></td></tr><tr><td><code>xml_tag_mismatch</code></td><td>源/译 XML 标签多重集合不一致（标签爆裂或丢失）</td><td>error</td><td>❌ 硬规则</td><td></td></tr></tbody></table><p><code>source_residual</code> 按语言对自动启用；源语言为 <code>auto</code> 时不生效。19 项 per-batch checker 可在 <code>qa.checks</code> 中按名启用/排除；<code>duplicate_source_divergence</code> 为文档级检查（跨段对比），始终随 QA 引擎运行，不必也不能在 <code>qa.checks</code> 中排除。<code>ruby_restore_incomplete</code> / <code>ruby_tag_loss</code> 由翻译轮的注音守恒逻辑产出，不属 <code>qa.checks</code> 可选名，但会随段落问题进入筛选与统计。</p><p><code>punctuation_missing</code>、<code>punctuation_surplus</code>、<code>punctuation_wrap_loss</code> 与 <code>punctuation_pairing</code> 四者互补不重复：源文某类包裹标点在译文中<strong>完全缺失</strong>时报 <code>punctuation_missing</code>；译文多出源文所无的<strong>成对</strong>包裹标点（疑似多译出）时报 <code>punctuation_surplus</code>；译文仍有该类标点但<strong>配对不平衡</strong>时才报 <code>punctuation_pairing</code>；源文<strong>整段被成对引号包裹</strong>、译文首尾完全丢失外层引号时报 <code>punctuation_wrap_loss</code>（补 <code>punctuation_missing</code> 对「内层新增引号致计数非零」的盲区）。<code>punctuation_missing</code> 与 <code>punctuation_wrap_loss</code> 报出的安全子集可由执行计划的 <a href="/LinguaFlow/zh/guide/translation-config.html#执行计划">本地改写轮次</a> 自动修复（另有 <code>width_mix_normalize</code> 规则修复全/半角混用），详见 <a href="/LinguaFlow/zh/guide/pipeline.html#本地改写-correct">流水线与原理 · 本地改写</a>。</p><div class="tip custom-block"><p class="custom-block-title">原文结构不会被误报为质量问题</p><p>HTML 标签、链接等原文结构在译文中会被还原回来，但 QA 引擎会把这些区段标为<strong>保护区</strong>，标点配对、空白、全/半角混用等 checker 在保护区上<strong>自动跳过</strong>——只检查译文真正写出来的文字。所以一份满是 HTML 标签的译文不会再因为标签里的英文符号被报一堆 <code>punctuation_pairing</code> / <code>width_mix</code>。<code>xml_tag_mismatch</code> 比对标签时还会<strong>排除 <code>&lt;ruby&gt;</code> 注音标签族</strong>，避免与 Ruby 还原策略冲突。详见 <a href="/LinguaFlow/zh/guide/pipeline.html#保护区-不被原文结构干扰">流水线与原理 · 保护区</a>。</p></div><div class="tip custom-block"><p class="custom-block-title">词表上的禁译 / 强制</p><p><code>forbidden_term</code> 与 <code>term_inconsistency</code> 由 <a href="/LinguaFlow/zh/guide/glossary.html#禁译-forbidden-与强制-mandatory">术语表</a> 的 <code>forbidden</code> / <code>mandatory</code> 属性驱动，先配好条目才会触发这两类问题。</p></div><h3 id="语义质检-code" tabindex="-1">语义质检 code <a class="header-anchor" href="#语义质检-code" aria-label="Permalink to &quot;语义质检 code&quot;">​</a></h3><p>语义质检由执行计划 <code>semantic_qa</code> 轮次运行 LLM 产出，覆盖规则质检难以捕获的语义错误。8 个 code 按优先级划界（同一缺陷同时命中两类时取最具体者）：</p><table tabindex="0"><thead><tr><th>code</th><th>含义</th></tr></thead><tbody><tr><td><code>term_fidelity</code></td><td>词表外术语的语义误译，或非词表称呼的前后漂移</td></tr><tr><td><code>calque</code></td><td>照搬源语搭配/构词/句式的逐结构借译</td></tr><tr><td><code>omission</code></td><td>译文整体完整但丢失某个分句/短语/语义单元（段整空归规则）</td></tr><tr><td><code>addition</code></td><td>译文凭空塞入源文没有的语义内容（仅长度异常归规则）</td></tr><tr><td><code>grammar</code></td><td>目标语实际不合语法（主谓/助词/时态等）</td></tr><tr><td><code>register</code></td><td>语体/敬体/语气与源文不对位</td></tr><tr><td><code>naturalness</code></td><td>语义可懂但表达生硬直译，作流畅度兜底</td></tr><tr><td><code>mistranslation</code></td><td>非术语/非借译/非上述范畴的一般语义误译，作语义兜底</td></tr></tbody></table><p>语义质检本轮<strong>不做裁决降噪</strong>，结果以 <code>warning</code> 写入段落、直接进人审，因此调节扫描范围以控制成本很重要，见 <a href="/LinguaFlow/zh/guide/translation-config.html#语义质检">翻译配置 · 使用 · 语义质检</a>。</p><div class="warning custom-block"><p class="custom-block-title">规则与语义不重复</p><p>语义质检 prompt 内置排除上表的全部「规则负责」code；规则 N/A 的问题才由语义负责。要让两类问题互相不污染，保持规则质检部分启用即可。</p></div><h3 id="质量指示" tabindex="-1">质量指示 <a class="header-anchor" href="#质量指示" aria-label="Permalink to &quot;质量指示&quot;">​</a></h3><p>检测到问题后，段落表格的质量指标列会显示对应的状态标记：</p><ul><li><strong>绿色</strong> — 无问题</li><li><strong>黄色</strong> — 轻微问题（如源语残留、长度轻微偏差、<code>warning</code> 级语义问题）</li><li><strong>红色</strong> — 严重问题（如过长/过短超出阈值、重复、未翻译、禁译命中）</li></ul><p>点击质量标记可查看详细诊断信息（含问题 code 与说明）。带 <code>span</code> 的问题会在译文相应区间高亮，悬停问题图标与文本区间可联动定位。</p><h3 id="质量检测配置" tabindex="-1">质量检测配置 <a class="header-anchor" href="#质量检测配置" aria-label="Permalink to &quot;质量检测配置&quot;">​</a></h3><p>在执行配置（Execution Profile）中调整质量检测参数：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">qa</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 是否启用规则质检</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  checks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 留空（undefined）表示启用全部确定性 checker</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - length_ratio</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - untranslated</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - duplicate</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # - ...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # length_ratio 启用开关（旧字段，与 checks 名等价）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    min_ratio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 最小长度比（译文/原文）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    max_ratio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 最大长度比对</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    unit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">char</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # char 或 word</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  repetition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 相邻重复（duplicate）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  untranslated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 未翻译</span></span></code></pre></div><ul><li><code>qa.checks</code> 为 <code>undefined</code>（CLI/界面未填写）→ 启用 <strong>全部</strong> 19 项 per-batch checker（文档级 <code>duplicate_source_divergence</code> 始终随引擎运行，不在此列）</li><li><code>qa.checks</code> 为具体列表 → 仅启动名单中按 <code>Checker.Name()</code> 精确匹配的 checker；<code>ruby_restore_incomplete</code> / <code>ruby_tag_loss</code> 由翻译轮注音守恒产出，不属可选名</li><li>列表为空数组时视为「等价于全部」并自动改回 <code>nil</code></li></ul><p>规则质检的 select-by-name（界面上的「全部启用 / 自定义选择」）是在配置编辑器里直接勾选具体检查项启用，详见 <a href="/LinguaFlow/zh/guide/translation-config.html#执行配置">翻译配置 · 使用</a>。</p><h2 id="质量问题裁决" tabindex="-1">质量问题裁决 <a class="header-anchor" href="#质量问题裁决" aria-label="Permalink to &quot;质量问题裁决&quot;">​</a></h2><p>质检报出的问题未必都是真问题——专有名词被误判为源语残留、有意保留的标点被报缺失等。LinguaFlow 支持对单条质量问题下<strong>裁决</strong>，把误报标记为「不是问题」（<code>dismissed</code>），让它不再干扰审校与修复。</p><h3 id="裁决从哪来" tabindex="-1">裁决从哪来 <a class="header-anchor" href="#裁决从哪来" aria-label="Permalink to &quot;裁决从哪来&quot;">​</a></h3><p>裁决有两种来源，效果一致——都写入问题的 <code>disposition</code> 字段，<code>dismissed</code> 的问题被视为已处置，不再计入筛选/统计，也不再触发本地改写修复：</p><table tabindex="0"><thead><tr><th>来源</th><th>谁判定</th><th>何时发生</th></tr></thead><tbody><tr><td>AI 裁决（<code>adjudicate</code> 轮）</td><td>LLM</td><td>执行计划中安排的裁决轮次，对软规则问题逐条复核</td></tr><tr><td>人工裁决</td><td>审校者</td><td>审校时在段落界面手动驳回</td></tr></tbody></table><h3 id="人工驳回-撤销裁决" tabindex="-1">人工驳回 / 撤销裁决 <a class="header-anchor" href="#人工驳回-撤销裁决" aria-label="Permalink to &quot;人工驳回 / 撤销裁决&quot;">​</a></h3><p>在段落列表中对单条质量问题操作：</p><ul><li><strong>桌面端</strong>：悬停问题图标，在弹出的详情浮层中点击「判定不是问题」</li><li><strong>移动端</strong>：点击问题标签打开详情，再点击「判定不是问题」</li></ul><p>驳回时会弹出确认框，可填写可选的<strong>裁决说明</strong>（如「专有名词，有意保留」）。确认后该问题变为「已驳回」：</p><ul><li>桌面端显示为灰色圆线图标，移动端为灰化带删除线的问题标签</li><li>对应译文高亮改为灰色删除线（暗色模式下用低对比度样式，避免刺眼）</li><li>详情中显示裁决者、裁决时间与说明</li></ul><div class="tip custom-block"><p class="custom-block-title">撤销裁决</p><p>误判了可以撤回：已驳回问题的操作入口会变为「撤销裁决」，确认后恢复为待处理质量问题并提示成功。撤销会清空该问题上的裁决者、时间与说明。</p></div><p>问题正在处理或保存时，对应的裁决操作会暂时禁用，待写入完成后再恢复。</p><h3 id="裁决与重算" tabindex="-1">裁决与重算 <a class="header-anchor" href="#裁决与重算" aria-label="Permalink to &quot;裁决与重算&quot;">​</a></h3><p>手动编辑译文后会重跑即时 QA。只要问题的指纹（<code>code</code> + <code>matched_text</code>）没变，已有的非未决裁决会被<strong>保留</strong>——你标过的「不是问题」不会因为重新质检而被冲掉。指纹消失（问题不再报出）的裁决随之清除，新出现或指纹变化的问题保持 <code>pending</code>。</p><div class="info custom-block"><p class="custom-block-title">仅即时 QA 范围内对账</p><p>手动编辑只重跑零配置确定性 QA（15 项确定性 checker + <code>ruby_tag_loss</code> 守恒比对），<code>length_ratio</code> / 术语表 / 文档级检查不在其列。这些未运行的 checker 产生的问题会在重算时被自然清除，属于预期行为。</p></div><p>接口细节见 <a href="/LinguaFlow/zh/api/">API 参考</a>。</p><h2 id="qa-重检" tabindex="-1">QA 重检 <a class="header-anchor" href="#qa-重检" aria-label="Permalink to &quot;QA 重检&quot;">​</a></h2><p>译文没变，但规则升级或执行配置调整之后，旧段落上的质检结果可能已经过时——想按<strong>当前</strong>的 QA 配置重新扫描既有译文，不必重跑翻译作业，用 <strong>QA 重检</strong> 即可。</p><h3 id="从哪里发起" tabindex="-1">从哪里发起 <a class="header-anchor" href="#从哪里发起" aria-label="Permalink to &quot;从哪里发起&quot;">​</a></h3><p>入口分布在工作区多个层级，按当前浏览范围自动带入重检目标：</p><ul><li>资源列表 / 资源浏览的工具栏（整个资源或当前章节）</li><li>段落面板工具栏（当前资源 / 章节，或先勾选段落限定选中范围）</li><li>选中段落后的浮动操作栏（选中段落）</li><li>EPUB 章节选择胶囊</li></ul><p>发起后选择一份<strong>启用了 QA 的执行配置</strong>，确认范围即开始重检。</p><h3 id="重检做什么" tabindex="-1">重检做什么 <a class="header-anchor" href="#重检做什么" aria-label="Permalink to &quot;重检做什么&quot;">​</a></h3><ul><li>按所选执行配置<strong>当前的 QA 配置</strong>与当前版本的规则实现，对范围内译文重跑确定性 QA 与文档级 <code>duplicate_source_divergence</code></li><li><strong>只写回 <code>quality_issues</code>，不改译文、不改段落状态</strong>——重检是纯质量视角的刷新</li><li>裁决对账：指纹相同的问题<strong>继承既有裁决</strong>（含人工 <code>dismissed</code>），不会把已判定「不是问题」的项复活；新出现的问题计为「新增」，指纹消失的计为「清除」</li><li>语义质检产出的问题与注音守恒码（<code>ruby_restore_incomplete</code> / <code>ruby_tag_loss</code>）<strong>原样保留</strong>——它们的维护者分别是语义质检轮与翻译/编辑写路径，重检不清除也不重算</li></ul><h3 id="结果怎么看" tabindex="-1">结果怎么看 <a class="header-anchor" href="#结果怎么看" aria-label="Permalink to &quot;结果怎么看&quot;">​</a></h3><p>重检完成后抽屉展示统计摘要：重检的段落/资源数、新增与清除的问题数、继承的裁决数、因无译文或并发修改而跳过的段落数，以及按资源的明细。选中范围内存在<strong>运行中任务</strong>的资源会被跳过并在结果中警告，避免与正在写入的作业互相覆盖——等任务结束再对这部分补一次重检即可。</p><p>接口契约见 <a href="/LinguaFlow/zh/api/#_14-qa-重检-qa-recheck">API 概述 · QA 重检</a>。</p><h2 id="截断与修复诊断" tabindex="-1">截断与修复诊断 <a class="header-anchor" href="#截断与修复诊断" aria-label="Permalink to &quot;截断与修复诊断&quot;">​</a></h2><p>模型响应偶尔会因输出 token 上限被截断，或带出格式瑕疵需要修复链介入。这些过程不再只藏在重试里，批次事件与预览诊断会把它们<strong>标注出来</strong>：</p><ul><li><strong>「输出被截断」标签</strong>（<code>truncated</code>）— 该批次的后端响应因 token 上限被截断（如 <code>finish_reason=length</code> / <code>max_tokens</code>）。截断的部分文本仍有效：修复链会抢救出最后完整值之前的有效前缀，缺失的条目进入重跑通道</li><li><strong>「解析修复」标签</strong>（<code>repaired</code>）— 响应解析时应用过的修复算子链（如 <code>json.close-braces</code>、<code>json.truncation-salvage</code>），按应用顺序列出，悬停可查看说明</li></ul><p>在 <a href="/LinguaFlow/zh/guide/projects.html#进度追踪">批次详情抽屉</a> 与 <a href="#单段修订预览">单段预览诊断</a> 中都能看到这两个标签。看到「输出被截断」不必紧张：残缺条目会自动重跑，无需人工干预；如果频繁出现，说明批次过大或 <code>max_tokens</code> 偏小，可调整执行计划里的批次参数或后端的 <code>max_tokens</code>。</p><h2 id="批注" tabindex="-1">批注 <a class="header-anchor" href="#批注" aria-label="Permalink to &quot;批注&quot;">​</a></h2><p>在审校过程中可以为每个段落添加批注，记录修改原因或翻译建议。</p><p>批注存储在段落的 <code>review_comment</code> 字段中，在段落列表中可以查看。</p><div class="info custom-block"><p class="custom-block-title">使用场景</p><ul><li>记录修改翻译的原因</li><li>标记需要后续复查的术语</li><li>为其他审校者提供参考意见</li></ul></div><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>当翻译段落较多时，可以使用批量操作提高效率。</p><h3 id="选择段落" tabindex="-1">选择段落 <a class="header-anchor" href="#选择段落" aria-label="Permalink to &quot;选择段落&quot;">​</a></h3><p>在段落列表中勾选需要操作的段落，底部会弹出浮动操作栏。</p><h3 id="批量审批" tabindex="-1">批量审批 <a class="header-anchor" href="#批量审批" aria-label="Permalink to &quot;批量审批&quot;">​</a></h3><p>选择多个段落后，点击浮动操作栏的 <strong>通过</strong> 按钮，一次性审批所有选中的段落。</p><h3 id="批量拒绝" tabindex="-1">批量拒绝 <a class="header-anchor" href="#批量拒绝" aria-label="Permalink to &quot;批量拒绝&quot;">​</a></h3><p>选择多个段落后，点击浮动操作栏的 <strong>拒绝</strong> 按钮，一次性拒绝所有选中的段落。</p><div class="info custom-block"><p class="custom-block-title">批量操作说明</p><ul><li>批量审批时，仅对状态为「已翻译」「已修改」「已驳回」的段落生效</li><li>批量拒绝时，仅对状态为「已翻译」「已修改」的段落生效</li><li>不满足条件的段落会被自动跳过</li></ul></div><h2 id="搜索替换" tabindex="-1">搜索替换 <a class="header-anchor" href="#搜索替换" aria-label="Permalink to &quot;搜索替换&quot;">​</a></h2><p>译文中存在同类问题（术语不统一、多余空格、标点风格不一致等）时，不必逐段编辑：在段落面板工具栏点 <strong>搜索替换</strong>，在滑出的抽屉中对当前资源的<strong>译文</strong>批量查找替换，原文不受影响。</p><h3 id="操作流程" tabindex="-1">操作流程 <a class="header-anchor" href="#操作流程" aria-label="Permalink to &quot;操作流程&quot;">​</a></h3><ol><li>输入查找内容与替换文本（替换文本留空表示删除匹配内容）</li><li>按需调整匹配选项： <ul><li><strong>匹配方式</strong> — 字面子串（默认）或正则（RE2 语法，替换文本支持 <code>$1</code> 捕获引用）</li><li><strong>区分大小写</strong> — 默认开启</li><li><strong>全字匹配</strong> — 只匹配完整词汇，不含子串命中；仅子串模式生效，正则模式下可用 <code>\\b</code> 边界替代</li></ul></li><li>选择作用范围：<strong>全部命中段落</strong>，或 <strong>仅选中段落</strong>（需先在段落列表勾选段落）</li><li>点 <strong>预览</strong> 查看影响范围：受影响段落数、总命中次数，以及样本的「替换前 / 替换后」对照（样本过多时仅显示前若干条）</li><li>确认无误后点 <strong>应用替换</strong>。应用前会弹确认框（将对 N 个段落执行共 M 处替换，替换后段落状态会标记为已编辑）；应用后展示已应用 / 跳过的段落数，跳过原因逐条列出</li></ol><div class="warning custom-block"><p class="custom-block-title">预览会过期</p><p>预览之后修改任何查找参数或作用范围，已有预览即标记过期，必须重新预览才能应用。</p></div><div class="info custom-block"><p class="custom-block-title">替换后会发生什么</p><p>替换只作用于译文。被替换的段落状态会变为「已编辑」，并自动重新执行规则质检；替换后译文为空的段落会被跳过，不会产生空译文。</p></div><h3 id="撤销替换" tabindex="-1">撤销替换 <a class="header-anchor" href="#撤销替换" aria-label="Permalink to &quot;撤销替换&quot;">​</a></h3><p>抽屉底部的 <strong>撤销上次替换</strong> 可回滚最近一次替换，再次撤销相当于重做。已被后续编辑的段落会被跳过。撤销历史在服务端保留一段时间（默认 90 天，由 <code>server.revision_retention</code> 配置，见 <a href="/LinguaFlow/zh/guide/configuration.html#server-—-服务器">配置文件与环境变量</a>），超过保留期或切换资源后无法再撤销。接口契约见 <a href="/LinguaFlow/zh/api/#_13-段落搜索替换-search-replace">API 概述 · 段落搜索替换</a>。</p><h2 id="一键审批" tabindex="-1">一键审批 <a class="header-anchor" href="#一键审批" aria-label="Permalink to &quot;一键审批&quot;">​</a></h2><p>在资源详情页，可以使用 <strong>全部审批</strong> 功能，将该资源下所有符合条件的段落一次性审批通过。</p><ul><li>将所有「已翻译」「已修改」「已驳回」状态的段落转为「已批准」</li><li>审批后自动清除这些段落的审校批注</li></ul><h2 id="重新翻译已驳回段落" tabindex="-1">重新翻译已驳回段落 <a class="header-anchor" href="#重新翻译已驳回段落" aria-label="Permalink to &quot;重新翻译已驳回段落&quot;">​</a></h2><p>对于已驳回的段落，可以触发 <strong>重新翻译</strong>，将这些段落重置为「待审校」状态并重新进入翻译队列。</p><ul><li>所有「已驳回」状态的段落会被重置为「待审校」</li><li>清除审校者信息和审校批注</li></ul><h2 id="自动审批" tabindex="-1">自动审批 <a class="header-anchor" href="#自动审批" aria-label="Permalink to &quot;自动审批&quot;">​</a></h2><p>创建翻译任务时，可以开启 <strong>自动审批</strong> 选项：</p><ul><li>开启后，翻译完成的段落会直接标记为「已批准」，无需手动审校</li><li>适用于对翻译质量要求不高的场景或初稿翻译</li></ul><p>在任务创建面板中，勾选「翻译完成后自动审批」即可启用。</p><h2 id="审校进度" tabindex="-1">审校进度 <a class="header-anchor" href="#审校进度" aria-label="Permalink to &quot;审校进度&quot;">​</a></h2><p>工作区顶部的进度条显示翻译和审校进度：</p><ul><li><strong>蓝色进度条</strong> — 已翻译段落占比（包含已翻译、已修改、已批准）</li><li><strong>绿色进度条</strong> — 已审批段落占比（仅已批准）</li></ul><p>段落分组也会显示每组的已批准数量和占比。</p><h2 id="搜索与筛选" tabindex="-1">搜索与筛选 <a class="header-anchor" href="#搜索与筛选" aria-label="Permalink to &quot;搜索与筛选&quot;">​</a></h2><p>在段落列表中可以搜索和筛选，快速定位需要审校的段落。</p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h3><p>在段落列表顶部的搜索框中输入关键词，可以筛选出包含该内容的段落。输入搜索词后，还可以进一步控制匹配范围：</p><ul><li><strong>字段范围</strong> — 下拉选择「原文+译文」（默认）/「仅原文」/「仅译文」</li><li><strong>区分大小写</strong> — 「Aa」按钮切换</li><li><strong>结果计数</strong> — 工具栏显示「已加载 N / 共 M 段」，方便确认是否还有更多结果</li></ul><div class="tip custom-block"><p class="custom-block-title">搜索与筛选可叠加</p><p>搜索可以与状态筛选同时使用。例如，先筛选「已驳回」状态，再搜索特定术语，快速找到需要修改的段落。</p></div><h3 id="按状态筛选" tabindex="-1">按状态筛选 <a class="header-anchor" href="#按状态筛选" aria-label="Permalink to &quot;按状态筛选&quot;">​</a></h3><p>在段落列表中可以按状态筛选：</p><ul><li>筛选「已翻译」— 查看待审校的段落</li><li>筛选「已驳回」— 查看需要重新处理的段落</li><li>筛选「已批准」— 查看已通过的段落</li><li>筛选「已修改」— 查看人工编辑过的段落</li></ul><h3 id="按质量问题筛选" tabindex="-1">按质量问题筛选 <a class="header-anchor" href="#按质量问题筛选" aria-label="Permalink to &quot;按质量问题筛选&quot;">​</a></h3><p>段落列表支持按质量问题过滤，快速定位需关注的段落。问题类型筛选已从平铺的标签改为<strong>分组下拉</strong>（可搜索、可清空，占位「按问题类型筛选」），按下列 8 个分组组织全部 30 个可筛选 code：</p><table tabindex="0"><thead><tr><th>分组</th><th>包含的 code</th></tr></thead><tbody><tr><td>硬规则</td><td><code>untranslated</code>、<code>duplicate</code>、<code>source_residual</code>、<code>length_ratio</code></td></tr><tr><td>排版标点</td><td><code>punctuation_pairing</code>、<code>punctuation_missing</code>、<code>punctuation_surplus</code>、<code>punctuation_wrap_loss</code>、<code>whitespace_irregular</code>、<code>repeated_space</code>、<code>width_mix</code>、<code>script_mismatch</code></td></tr><tr><td>数字链接</td><td><code>number_mismatch</code>、<code>url_email_mismatch</code></td></tr><tr><td>占位标签</td><td><code>leftover_placeholder</code>、<code>xml_tag_mismatch</code>、<code>ruby_restore_incomplete</code>、<code>ruby_tag_loss</code></td></tr><tr><td>术语</td><td><code>forbidden_term</code>、<code>term_inconsistency</code>、<code>term_fidelity</code></td></tr><tr><td>语义质量</td><td><code>calque</code>、<code>naturalness</code>、<code>mistranslation</code>、<code>omission</code>、<code>addition</code>、<code>grammar</code>、<code>register</code></td></tr><tr><td>字幕</td><td><code>subtitle_line_count</code></td></tr><tr><td>同源偏差</td><td><code>duplicate_source_divergence</code></td></tr></tbody></table><p>30 个可筛选 code 由全部 per-batch checker（19 项）、注音守恒 code（2 项）、文档级检查（1 项）与语义质检 code（8 项）合并派生；后续新增 checker 会自动出现在筛选列表中。可与状态筛选、关键词搜索叠加。例如：先筛「排版标点」分组里的 <code>punctuation_missing</code>，集中处理译文丢失引号的段落；或筛「语义质量」分组里的 <code>calque</code> + <code>warning</code> 专看语义质检报告出的逐字直译问题。</p><div class="tip custom-block"><p class="custom-block-title">已驳回问题不计入筛选</p><p>筛选与质量统计只看<strong>待处理</strong>问题——已被裁决为 <code>dismissed</code>（驳回）的问题视为已处置，不会让段落因它出现在筛选结果里。详见 <a href="#质量问题裁决">质量问题裁决</a>。</p></div><div class="tip custom-block"><p class="custom-block-title">配合 AI 质量裁决 / 语义质检 / 本地改写 / LLM 修订</p><ul><li>规则质检偏敏感，可在执行计划中加 <strong>质量裁决</strong>（<code>adjudicate</code>）轮次，对 <code>source_residual</code>、<code>punctuation_surplus</code>、<code>length_ratio</code> 等软规则逐条复核、将误报标记为 <code>dismissed</code></li><li>规则查不出来的语义错误，可加 <strong>语义质检</strong>（<code>semantic_qa</code>）轮次补足，结果以 <code>warning</code> 直接进人审，无需再裁决</li><li><code>punctuation_missing</code> / <code>punctuation_wrap_loss</code> / <code>width_mix</code> 等可机械修复的安全问题，可加 <strong>本地改写</strong>（<code>correct</code>）轮次自动改写译文消除问题，无需调 LLM</li><li>语义质检报出的 <code>pending</code> 语义问题（误译、仿译、漏译等），可加 <strong>LLM 修订</strong>（<code>revise</code>）轮次对现有译文做定点最小修订，调 LLM、系统提示词内置</li><li>四类轮次都放在翻译轮次之后，详见 <a href="/LinguaFlow/zh/guide/pipeline.html#规则质检与-ai-质量裁决">流水线与原理 · 规则质检与 AI 质量裁决</a></li></ul></div><h3 id="任务级资源警告" tabindex="-1">任务级资源警告 <a class="header-anchor" href="#任务级资源警告" aria-label="Permalink to &quot;任务级资源警告&quot;">​</a></h3><p>作业执行过程中若某资源在语义质检扫描阶段出现软警告（如失败但允许继续），会在资源详情页与进度卡片中显示 <code>warning_message</code>，提示您此资料的质检不完整，需人工补查。</p><h2 id="单段修订预览" tabindex="-1">单段修订预览 <a class="header-anchor" href="#单段修订预览" aria-label="Permalink to &quot;单段修订预览&quot;">​</a></h2><p>正式作业之外，想对某段的语义问题先看 LLM 修订效果再决定是否写回，可用段落操作菜单里的 <strong>修订预览</strong>：</p><ol><li>在段落行操作菜单点 <strong>修订预览</strong>（段落须已翻译/已修改、译文非空，且有至少一条 <code>pending</code> 语义 issue）</li><li>选择执行计划（须含 <code>revise</code> 轮；只有 <code>translate</code> 轮时后端会合成默认修订轮），可选收窄要修复的语义 issue 范围</li><li>发起修订，抽屉内对比原文、原译文与修订后译文，查看修复目标、最终质量问题与用量摘要</li><li>满意后点 <strong>应用</strong> 写回（短期签名令牌；段落基线变化即失效，需重新预览）</li></ol><p>修订预览与 <a href="/LinguaFlow/zh/guide/translation-config.html#单段试译">单段试译预览</a> 共用并发限制与应用端点，区别在于试译从原文生成全新译文，修订是以段落上 <code>pending</code> 语义 issue 为目标对现有译文做定点最小修订。接口字段见 <a href="/LinguaFlow/zh/guide/translation-config-reference.html#单段预览-preview">翻译配置 · 参考 · 单段预览</a>。</p><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">审校建议</p><ol><li><strong>分批审校</strong> — 按章节或段落分批审校，避免疲劳</li><li><strong>关注术语</strong> — 重点检查专业术语的翻译是否一致（参考 <code>term_inconsistency</code> / <code>forbidden_term</code>）</li><li><strong>保持上下文</strong> — 审校时注意段落之间的连贯性</li><li><strong>记录批注</strong> — 为重要的修改添加批注，方便后续参考</li><li><strong>善用高亮</strong> — 用问题区间的悬停联动，快速确认报告点对应的真实文本</li><li><strong>善用筛选</strong> — 按状态与质量问题筛选，优先处理有问题的段落</li><li><strong>批量操作</strong> — 段落较多时使用批量审批/拒绝提高效率</li><li><strong>裁决降噪</strong> — 启用质量裁决轮次，减少源语残留、长度异常的误报干扰</li><li><strong>语义补盲</strong> — 规则查不出来的语义错误，再用语义质检轮次补足</li><li><strong>机械修复</strong> — 对译文丢引号（<code>punctuation_missing</code> / <code>punctuation_wrap_loss</code>）、全/半角混用（<code>width_mix</code>）等可确定修复的安全问题，启用本地改写轮次自动消除</li><li><strong>LLM 定点修订</strong> — 语义质检报出的 <code>mistranslation</code> / <code>calque</code> / <code>omission</code> 等 <code>pending</code> 语义问题，启用 LLM 修订（<code>revise</code>）轮次对现有译文做最小改动定点修订，或用单段修订预览先看效果</li></ol></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>阅读 <a href="/LinguaFlow/zh/guide/glossary.html">术语表管理</a> 了解术语管理（含禁译 / 强制）</li><li>阅读 <a href="/LinguaFlow/zh/guide/pipeline.html">流水线与原理</a> 了解质检、裁决、语义质检、修订如何流转</li><li>阅读 <a href="/LinguaFlow/zh/guide/translation-config.html">翻译配置 · 使用</a> 了解如何编排 <code>semantic_qa</code> / <code>adjudicate</code> / <code>revise</code> 轮次和按项启用 QA checker</li></ul>`,144)])])}const g=e(i,[["render",s]]);export{u as __pageData,g as default};
